CREATE TABLE `local_recovery_run_assets` (
	`workspace_id` text NOT NULL,
	`device_id` text NOT NULL,
	`epoch_id` text NOT NULL,
	`checkpoint_id` text NOT NULL,
	`descriptor` text NOT NULL,
	`created_at` integer NOT NULL,
	PRIMARY KEY(`workspace_id`, `device_id`, `epoch_id`, `checkpoint_id`),
	CONSTRAINT "local_recovery_run_assets_identity" CHECK(length(trim("local_recovery_run_assets"."workspace_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_run_assets"."workspace_id",char(0))=0 AND length(trim("local_recovery_run_assets"."device_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_run_assets"."device_id",char(0))=0 AND length(trim("local_recovery_run_assets"."epoch_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_run_assets"."epoch_id",char(0))=0 AND length(trim("local_recovery_run_assets"."checkpoint_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_run_assets"."checkpoint_id",char(0))=0),
	CONSTRAINT "local_recovery_run_assets_descriptor" CHECK(json_valid("local_recovery_run_assets"."descriptor") AND json_type("local_recovery_run_assets"."descriptor",'$.version') IS 'integer' AND json_extract("local_recovery_run_assets"."descriptor",'$.version') IS 1 AND json_type("local_recovery_run_assets"."descriptor",'$.binding.checkpoint.version') IS 'integer' AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.checkpoint.version') IS 1 AND json_type("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.version') IS 'integer' AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.version') IS 1 AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.checkpoint.checkpoint.checkpoint.checkpoint.checkpoint.identity.workspaceId') IS "local_recovery_run_assets"."workspace_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.checkpoint.checkpoint.checkpoint.checkpoint.checkpoint.identity.deviceId') IS "local_recovery_run_assets"."device_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.checkpoint.checkpoint.checkpoint.checkpoint.checkpoint.identity.epochId') IS "local_recovery_run_assets"."epoch_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.checkpoint.checkpoint.checkpoint.checkpoint.checkpoint.identity.checkpointId') IS "local_recovery_run_assets"."checkpoint_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.identity.workspaceId') IS "local_recovery_run_assets"."workspace_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.identity.deviceId') IS "local_recovery_run_assets"."device_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.identity.epochId') IS "local_recovery_run_assets"."epoch_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.identity.checkpointId') IS "local_recovery_run_assets"."checkpoint_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.identity.schemaId') IS json_extract("local_recovery_run_assets"."descriptor",'$.binding.checkpoint.checkpoint.checkpoint.checkpoint.checkpoint.identity.schemaId') AND json_type("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.version') IS 'integer' AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.version') IS 1 AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.checkpoint.identity.workspaceId') IS "local_recovery_run_assets"."workspace_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.checkpoint.identity.deviceId') IS "local_recovery_run_assets"."device_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.checkpoint.identity.epochId') IS "local_recovery_run_assets"."epoch_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.checkpoint.identity.checkpointId') IS "local_recovery_run_assets"."checkpoint_id" AND json_type("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.localCheckpoint.version') IS 'integer' AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.localCheckpoint.version') IS 1 AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.localCheckpoint.identity.workspaceId') IS "local_recovery_run_assets"."workspace_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.localCheckpoint.identity.deviceId') IS "local_recovery_run_assets"."device_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.localCheckpoint.identity.epochId') IS "local_recovery_run_assets"."epoch_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.localCheckpoint.identity.checkpointId') IS "local_recovery_run_assets"."checkpoint_id" AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.localCheckpoint.identity.schemaId') IS json_extract("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.identity.schemaId') AND json_extract("local_recovery_run_assets"."descriptor",'$.assetCheckpoint.binding.checkpoint.identity.schemaId') IS json_extract("local_recovery_run_assets"."descriptor",'$.binding.localCheckpoint.identity.schemaId'))
);
